a('pro-BNP',[('pro','propeptide (précurseur)'),('B','de type B'),('N','Natriurétique'),('P','Peptide')],'Propeptide natriurétique de type B','<p>Précurseur clivé par la corine et la furine en BNP actif et NT-proBNP inactif.</p>','np')
a('pré-pro-BNP',[('pré','pré- (porteur du peptide signal)'),('pro','propeptide'),('B','de type B'),('N','Natriurétique'),('P','Peptide')],'Pré-propeptide natriurétique de type B','<p>Forme initiale synthétisée dans le cardiomyocyte ; la perte du peptide signal donne le pro-BNP.</p>','np')
a('NPR-A',[('N','Natriuretic'),('P','Peptide'),('R','Receptor'),('A','type A')],'Récepteur des peptides natriurétiques de type A','<p>Récepteur à activité guanylate cyclase : sa stimulation par le BNP produit du GMPc (natriurèse, vasodilatation).</p>')
a('NPR-C',[('N','Natriuretic'),('P','Peptide'),('R','Receptor'),('C','type C (clairance)')],'Récepteur de clairance des peptides natriurétiques','<p>Internalise et dégrade les peptides natriurétiques ; voie d’élimination du BNP avec la néprilysine.</p>')
