a('ST',[('S','fin de l’onde S'),('T','début de l’onde T')],'Segment ST de l’électrocardiogramme','<p>Segment compris entre la fin du QRS et le début de l’onde T ; ses déplacements traduisent une ischémie ou une lésion myocardique.</p>')
a('BBG',[('B','Bloc'),('B','de Branche'),('G','Gauche')],'Bloc de branche gauche','<p>Retard de conduction dans la branche gauche du faisceau de His : QRS ≥ 120 ms, aspect QS ou rS en V1, R large crocheté en V6. Crée un asynchronisme de contraction.</p>','crt')
a('IRM',[('I','Imagerie'),('R','par Résonance'),('M','Magnétique')],'Imagerie par résonance magnétique','<p>Référence pour les volumes, la FEVG et la caractérisation tissulaire myocardique.</p>','irm')
a('Ciné-IRM',[('Ciné','Cinématographique (images animées)'),('I','Imagerie'),('R','par Résonance'),('M','Magnétique')],'Imagerie par résonance magnétique en mode cinématographique','<p>Séquences animées sur le cycle cardiaque : mesure de référence des volumes et de la FEVG.</p>','irm')
a('T1',[('T','Temps de relaxation'),('1','longitudinale')],'Temps de relaxation longitudinale (IRM)','<p>Le T1 natif augmente avec la fibrose, l’œdème et l’amylose ; le calcul du volume extracellulaire en dérive.</p>','irm')
