a('PTD',[('P','Pression'),('T','Télé-'),('D','Diastolique')],'Pression télédiastolique','<p>Pression intraventriculaire en fin de diastole ; reflet de la précharge et de la compliance.</p>','pvloop')
a('RPVTS',[('R','Relation'),('P','Pression-'),('V','Volume'),('T','Télé-'),('S','Systolique')],'Relation pression-volume télésystolique','<p>Droite reliant les points télésystoliques pour différentes charges ; sa pente (élastance) mesure la contractilité.</p>','pvloop')
a('RPVTD',[('R','Relation'),('P','Pression-'),('V','Volume'),('T','Télé-'),('D','Diastolique')],'Relation pression-volume télédiastolique','<p>Courbe exponentielle ; sa raideur reflète la compliance ventriculaire, anormalement raide dans l’ICFEp.</p>','pvloop')
