a('FA',[('F','Fibrillation'),('A','Auriculaire')],'Fibrillation auriculaire','<p>Arythmie auriculaire désorganisée ; cause et conséquence fréquente de l’insuffisance cardiaque ; élève les peptides natriurétiques.</p>')
